(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-231":{scenario:{company:"Hải Đăng Global Forwarding",supervisor:{name:"Lê Minh Châu",role:{vi:"Trưởng phòng Khai thác Hàng xuất",en:"Export Operations Manager"}},ref_code:"HBL-2604",title:{vi:"Đúng điều kiện cước. Đúng tấn cước.",en:"Right freight term. Right revenue ton."},brief:{vi:"Bạn phát hành vận đơn nhà HBL-2604 cho lô hàng lẻ (LCL) phụ tùng gang đúc xuất từ Hải Phòng đi Rotterdam, điều kiện FOB Hải Phòng theo Incoterms 2020; người mua chỉ định công ty bạn làm đại lý giao nhận. Phiếu cân tại kho CFS: 9600 kg; phiếu đo: 6,4 CBM. Đối chiếu HBL nháp với hồ sơ đã duyệt, sửa điều kiện thanh toán cước và cước biển LCL (USD, giá mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are issuing house bill HBL-2604 for an LCL shipment of cast iron parts from Hai Phong to Rotterdam, sold FOB Hai Phong under Incoterms 2020; the buyer nominated your company as forwarder. CFS weighing ticket: 9600 kg; measurement: 6.4 CBM. Compare the draft HBL with the approved file, correct the freight term and the LCL ocean freight (USD, simulated rate), then write an evidence-based report."},reference_title:{vi:"Hồ sơ lô hàng & biểu giá LCL đã duyệt · HBL-2604",en:"Approved shipment file & LCL tariff · HBL-2604"},fields:[{id:"FRT_TERM",label:{vi:"Điều kiện thanh toán cước trên HBL",en:"Freight term on the HBL"},initial:"FREIGHT PREPAID",expected:"FREIGHT COLLECT",choices:["FREIGHT PREPAID","FREIGHT COLLECT","AS ARRANGED"],reference:"Hợp đồng mua bán & booking",ref_value:{vi:"Hợp đồng: FOB Hải Phòng; người mua thuê phương tiện và trả cước chặng chính",en:"Contract: FOB Hai Phong; the buyer books and pays the main carriage"},hint:{vi:"Theo FOB, người mua chịu cước vận tải chính nên cước được thu tại nơi đến.",en:"Under FOB the buyer bears the main carriage, so freight is collected at destination."}},{id:"OCEAN_FRT",label:{vi:"Cước biển LCL (USD)",en:"LCL ocean freight (USD)"},initial:"268.8",expected:"403.2",reference:"Biểu giá LCL đã duyệt",ref_value:{vi:"42 USD/RT; 1 RT = 1 CBM hoặc 1000 kg, lấy số lớn hơn (mô phỏng)",en:"42 USD/RT; 1 RT = 1 CBM or 1000 kg, whichever is greater (simulated)"},hint:{vi:"Hàng nặng: quy trọng lượng ra tấn rồi so với số khối, tính cước theo số lớn hơn.",en:"Heavy cargo: convert weight to tonnes, compare with CBM and charge on the greater figure."}}],sop32:{vi:"Cước LCL tính theo W/M: tấn cước (RT) = max(số khối CBM, trọng lượng quy ra tấn); cước = RT x đơn giá; bài mô phỏng không làm tròn RT.",en:"LCL freight is charged W/M: revenue tons (RT) = max(CBM, weight in tonnes); freight = RT x rate; RT is not rounded in this training case."},context:{label:"FWD OPS / HBL-2604",metrics:[{label:{vi:"Trọng lượng cả bì",en:"Gross weight"},value:"9,600 kg"},{label:{vi:"Thể tích",en:"Volume"},value:"6.4 CBM"},{label:{vi:"Đơn giá mô phỏng",en:"Simulated rate"},value:"42 USD/RT"}]},crisis:{vi:"Bộ phận kinh doanh nhắn: “Khách quen, cứ khai 6400 kg trên HBL và bảng kê hàng cho cước tính theo khối. Hàng lẻ không ai cân lại đâu, tàu cắt máng chiều nay.”",en:"Sales messages you: “Loyal customer, just declare 6400 kg on the HBL and the cargo list so freight goes by volume. Nobody re-weighs LCL cargo, and the vessel cuts off this afternoon.”"},options:{safe:{vi:"Khai đúng 9600 kg theo phiếu cân, tính cước theo W/M, báo trưởng phòng; giải thích rủi ro an toàn xếp hàng, VGM và đề xuất báo giá hàng nặng riêng cho khách.",en:"Declare the true 9600 kg from the weighing ticket, charge W/M, inform the manager, explain the stowage safety and VGM risks and offer a dedicated heavy-cargo quote."},shortcut:{vi:"Khai 6400 kg trên HBL theo ý kinh doanh để kịp cắt máng và giữ khách.",en:"Declare 6400 kg on the HBL as Sales asks to make the cut-off and keep the customer."},wait:{vi:"Tạm giữ HBL, không trả lời kinh doanh và chờ khách tự gửi số liệu mới.",en:"Hold the HBL, ignore Sales and wait for the customer to send new figures."}},questions:{vi:["Vì sao HBL phải ghi FREIGHT COLLECT thay vì FREIGHT PREPAID? Điều khoản nào trong hợp đồng chứng minh?","Trình bày cách tính tấn cước theo W/M và rủi ro an toàn, pháp lý nếu khai thấp trọng lượng hàng."],en:["Why must the HBL show FREIGHT COLLECT instead of FREIGHT PREPAID? Which contract term proves it?","Explain how you calculated revenue tons under W/M and the safety and legal risks of under-declaring cargo weight."]},hints:{vi:["Đặt HBL nháp cạnh hợp đồng mua bán, đánh dấu điều kiện cước không khớp Incoterms.","So số khối với trọng lượng quy ra tấn, lấy số lớn hơn rồi nhân đơn giá theo SOP mục 3.2.","Đọc lại SOP mục 4.2: trọng lượng trên chứng từ phải đúng phiếu cân; áp lực khai sai phải báo cáo."],en:["Place the draft HBL next to the sales contract and flag the freight term that does not match the Incoterm.","Compare CBM with weight in tonnes, take the greater and multiply by the rate per SOP 3.2.","Re-read SOP 4.2: document weights must match the weighing ticket; pressure to misdeclare must be escalated."]}},learning:{summary:{vi:"Chuyên viên điều vận quốc tế đường biển và đường hàng không tổ chức vận chuyển hàng xuất nhập khẩu cho khách: đặt chỗ với hãng tàu, hãng bay, gom hàng lẻ, phát hành vận đơn nhà (HBL, HAWB), phối hợp đại lý nước ngoài, theo dõi lô hàng và xử lý phát sinh. Công việc đòi hỏi nắm chắc Incoterms, cách tính cước từng phương thức, quy định hàng nguy hiểm và chứng từ vận tải.",en:"An ocean and air freight forwarder organizes international carriage for import and export customers: booking space with carriers and airlines, consolidating LCL cargo, issuing house bills (HBL, HAWB), coordinating overseas agents, tracking shipments and handling exceptions. The role requires solid knowledge of Incoterms, rating for each mode, dangerous goods rules and transport documents."},responsibilities:{vi:["Nhận yêu cầu vận chuyển, kiểm tra Incoterms, loại hàng, trọng lượng, thể tích và đặt chỗ với hãng tàu, hãng bay.","Phát hành vận đơn nhà HBL/HAWB, manifest và gửi chứng từ trước cho đại lý tại nơi đến.","Tính cước theo W/M cho hàng lẻ đường biển và khối lượng tính cước cho hàng không, lập giấy báo nợ.","Kiểm tra khai báo hàng nguy hiểm theo IMDG Code, IATA DGR và xác nhận VGM trước giờ cắt máng.","Theo dõi lịch trình, xử lý chậm tàu, chuyển tải, hư hỏng và thông báo khách hàng kịp thời."],en:["Take transport requests, check Incoterms, cargo type, weight and volume, and book with carriers and airlines.","Issue HBL/HAWB and manifests and send pre-alert documents to the destination agent.","Rate LCL ocean cargo on W/M and air cargo on chargeable weight, and issue debit notes.","Check dangerous goods declarations under the IMDG Code and IATA DGR and confirm VGM before cut-off.","Monitor schedules, handle delays, transshipment and damage, and update customers promptly."]},competencies:[{name:{vi:"Incoterms & điều kiện cước",en:"Incoterms & freight terms"},desc:{vi:"Xác định bên trả cước, điểm chuyển rủi ro và ghi đúng prepaid, collect trên vận đơn.",en:"Identify who pays freight and where risk passes, and show prepaid or collect correctly on the bill."}},{name:{vi:"Tính cước đa phương thức",en:"Multimodal rating"},desc:{vi:"Áp dụng W/M cho LCL, tỷ lệ 1:6000 cho hàng không, phụ phí và đơn giá theo hợp đồng.",en:"Apply W/M for LCL, the 1:6000 ratio for air, surcharges and contract rates."}},{name:{vi:"Chứng từ vận tải",en:"Transport documentation"},desc:{vi:"Lập HBL, HAWB, manifest chính xác, khớp booking, phiếu cân và chứng từ thương mại.",en:"Produce accurate HBL, HAWB and manifests matching the booking, weighing ticket and trade documents."}},{name:{vi:"Hàng nguy hiểm & an toàn",en:"Dangerous goods & safety"},desc:{vi:"Nhận diện hàng nguy hiểm, yêu cầu khai báo đúng và từ chối nhận hàng khai sai.",en:"Recognize dangerous goods, require correct declarations and refuse misdeclared cargo."}},{name:{vi:"Phối hợp mạng lưới đại lý",en:"Agent network coordination"},desc:{vi:"Làm việc với hãng tàu, hãng bay, kho CFS và đại lý nước ngoài theo múi giờ và cam kết dịch vụ.",en:"Work with carriers, airlines, CFS warehouses and overseas agents across time zones and service commitments."}}],knowledge:{vi:["Incoterms 2020 của ICC: điểm chuyển giao rủi ro, chi phí và ảnh hưởng đến điều kiện cước trên vận đơn.","Bộ luật Hàng hải Việt Nam 2015 (số 95/2015/QH13) về hợp đồng vận chuyển hàng hóa và vận đơn đường biển.","Công ước Montreal 1999 về trách nhiệm của người vận chuyển hàng không quốc tế.","Bộ luật IMDG cho hàng nguy hiểm đường biển, IATA DGR cho đường hàng không và yêu cầu VGM của Công ước SOLAS.","Nghị định 163/2017/NĐ-CP về kinh doanh dịch vụ logistics."],en:["ICC Incoterms 2020: transfer of risk and cost and its effect on the freight term on the bill.","Vietnam Maritime Code 2015 (No. 95/2015/QH13) on contracts of carriage and ocean bills of lading.","Montreal Convention 1999 on the liability of international air carriers.","IMDG Code for sea dangerous goods, IATA DGR for air, and the SOLAS VGM requirement.","Decree 163/2017/ND-CP on logistics services business."]},tools:["Phần mềm quản lý giao nhận (Forwarding ERP)","Cổng đặt chỗ trực tuyến của hãng tàu, hãng bay","Nền tảng theo dõi container và chuyến bay","VNACCS/VCIS","Microsoft Excel"],kpis:{vi:["Tỷ lệ HBL/HAWB phát hành đúng ngay lần đầu, không phải sửa.","Tỷ lệ lô hàng đi đúng chuyến đã đặt chỗ.","Số khiếu nại, chi phí phát sinh do sai chứng từ (mục tiêu bằng 0).","Thời gian gửi chứng từ trước cho đại lý sau khi tàu chạy."],en:["Share of HBL/HAWB issued right first time without amendment.","Share of shipments loaded on the booked sailing or flight.","Complaints and extra costs caused by document errors (target zero).","Time to send pre-alert documents to the agent after departure."]},day:[{time:"08:00",vi:"Kiểm tra email đại lý nước ngoài, lịch tàu, chuyến bay và các lô sắp cắt máng.",en:"Check overseas agent emails, vessel and flight schedules and shipments near cut-off."},{time:"10:00",vi:"Đặt chỗ, xác nhận booking, nhận phiếu cân, phiếu đo hàng lẻ tại kho CFS.",en:"Book space, confirm bookings and collect LCL weighing and measurement tickets from the CFS."},{time:"13:30",vi:"Lập HBL nháp, đối chiếu hợp đồng, Incoterms và gửi khách xác nhận.",en:"Draft the HBL, check it against the contract and Incoterms and send it for customer approval."},{time:"15:30",vi:"Xác nhận VGM, khai báo hàng nguy hiểm nếu có và nộp chứng từ trước giờ cắt máng.",en:"Confirm VGM, file dangerous goods declarations if any and submit documents before cut-off."},{time:"17:30",vi:"Gửi pre-alert cho đại lý nơi đến, lập giấy báo nợ cước và cập nhật hệ thống.",en:"Send the pre-alert to the destination agent, issue freight debit notes and update the system."}],mistakes:{vi:["Ghi FREIGHT PREPAID trên HBL cho lô FOB mà người mua là bên trả cước.","Tính cước hàng lẻ theo số khối cho hàng nặng thay vì theo W/M.","Chấp nhận khai thấp trọng lượng hoặc khai sai hàng nguy hiểm để rẻ cước, gây rủi ro an toàn tàu và bị xử phạt."],en:["Showing FREIGHT PREPAID on the HBL of an FOB shipment where the buyer pays freight.","Charging heavy LCL cargo by volume instead of W/M.","Accepting under-declared weights or misdeclared dangerous goods to cut freight, endangering the vessel and inviting penalties."]},career:[{vi:"Nhân viên chứng từ giao nhận",en:"Forwarding documentation assistant"},{vi:"Chuyên viên khai thác đường biển & hàng không",en:"Ocean & air operations specialist"},{vi:"Trưởng nhóm khai thác giao nhận",en:"Forwarding operations team lead"},{vi:"Quản lý vận hành giao nhận quốc tế",en:"International freight operations manager"}],glossary:[{term:"HBL",vi:"Vận đơn nhà do công ty giao nhận phát hành cho người gửi hàng của mình.",en:"House bill of lading issued by the forwarder to its own shipper."},{term:"LCL",vi:"Hàng lẻ: hàng của nhiều chủ hàng được đóng chung một container tại kho CFS.",en:"Less than container load: cargo of several shippers consolidated in one container at a CFS."},{term:"W/M",vi:"Nguyên tắc tính cước theo trọng lượng hoặc thể tích, lấy giá trị lớn hơn quy ra tấn cước.",en:"Weight or measurement rule: freight is charged on whichever gives more revenue tons."},{term:"VGM",vi:"Khối lượng toàn bộ đã xác nhận của container theo yêu cầu SOLAS trước khi xếp lên tàu.",en:"Verified gross mass of a packed container required by SOLAS before loading."},{term:"Pre-alert",vi:"Thông báo kèm bản sao chứng từ gửi đại lý nơi đến trước khi hàng tới.",en:"Advance notice with document copies sent to the destination agent before arrival."}],quiz:[{q:{vi:"Lô hàng không nặng 120 kg, thể tích 1,2 m³, hệ số 6000 cm³/kg. Khối lượng tính cước là bao nhiêu?",en:"An air shipment weighs 120 kg with a volume of 1.2 m³, divisor 6000 cm³/kg. What is the chargeable weight?"},options:{vi:["120 kg","160 kg","200 kg","320 kg"],en:["120 kg","160 kg","200 kg","320 kg"]},answer:2,explain:{vi:"1,2 m³ = 1200000 cm³; chia 6000 được 200 kg, lớn hơn 120 kg nên tính theo 200 kg.",en:"1.2 m³ = 1200000 cm³; divided by 6000 gives 200 kg, which exceeds 120 kg, so 200 kg is charged."}},{q:{vi:"Theo FOB Incoterms 2020, ai trả cước vận tải chặng chính?",en:"Under FOB Incoterms 2020, who pays the main carriage?"},options:{vi:["Người mua","Người bán","Đại lý nơi đi","Ngân hàng"],en:["The buyer","The seller","The origin agent","The bank"]},answer:0,explain:{vi:"Theo FOB, người bán giao hàng lên tàu; người mua thuê tàu và trả cước chặng chính.",en:"Under FOB the seller delivers on board; the buyer contracts and pays the main carriage."}},{q:{vi:"Khách nhờ ghi pin lithium thành ‘phụ tùng điện tử’ để khỏi khai báo hàng nguy hiểm. Bạn làm gì?",en:"A customer asks you to describe lithium batteries as ‘electronic parts’ to avoid a dangerous goods declaration. What do you do?"},options:{vi:["Ghi theo khách vì hàng ít","Từ chối, yêu cầu khai báo và đóng gói theo quy định hàng nguy hiểm, báo trưởng phòng","Gửi đi rồi báo sau","Đổi sang đường biển để khỏi khai"],en:["Write it as asked since the quantity is small","Refuse, require DG declaration and packing per the rules, and inform the manager","Ship now and report later","Switch to ocean to avoid declaring"]},answer:1,explain:{vi:"Khai sai hàng nguy hiểm có thể gây cháy nổ trên tàu, máy bay; mọi phương thức đều bắt buộc khai báo đúng.",en:"Misdeclared dangerous goods can cause fires on ships and aircraft; every mode requires a correct declaration."}},{q:{vi:"Hàng lẻ 3 CBM, nặng 4500 kg, đơn giá 40 USD/RT. Cước là bao nhiêu?",en:"LCL cargo of 3 CBM weighs 4500 kg at 40 USD/RT. What is the freight?"},options:{vi:["120 USD","160 USD","150 USD","180 USD"],en:["120 USD","160 USD","150 USD","180 USD"]},answer:3,explain:{vi:"4500 kg = 4,5 tấn lớn hơn 3 CBM nên RT = 4,5; cước = 4,5 x 40 = 180 USD.",en:"4500 kg = 4.5 t exceeds 3 CBM, so RT = 4.5; freight = 4.5 x 40 = 180 USD."}}],tools_en:["Freight forwarding software (Forwarding ERP)","Carrier and airline online booking portals","Container and flight tracking platforms","VNACCS/VCIS","Microsoft Excel"]}}})})(window.KKR);
